class Solution {
public:
    int findLHS(vector<int>& nums) {
        unordered_map<int, int> counts;
        for (int n : nums) counts[n]++;
        int ans = 0;
        for (auto& pair : counts) {
            auto it = counts.find(pair.first + 1);
            if (it != counts.end()) {
                ans = max(ans, pair.second + it->second);
            }
        }
        return ans;
    }
};

class Solution {
    public int findLHS(int[] nums) {
        Map<Integer, Integer> counts = new HashMap<>();
        for (int n : nums) counts.put(n, counts.getOrDefault(n, 0) + 1);
        int ans = 0;
        for (int key : counts.keySet()) {
            if (counts.containsKey(key + 1)) {
                ans = Math.max(ans, counts.get(key) + counts.get(key + 1));
            }
        }
        return ans;
    }
}

var findLHS = function(nums) {
    const counts = new Map();
    for (const n of nums) counts.set(n, (counts.get(n) || 0) + 1);
    let ans = 0;
    for (const [key, val] of counts.entries()) {
        if (counts.has(key + 1)) {
            ans = Math.max(ans, val + counts.get(key + 1));
        }
    }
    return ans;
};
